package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;

/**
 * Create-owner step: rejects the request with a 429 when {@link #DAILY_LIMIT} or more owners
 * have already been registered on today's business day (by {@link Owner#getRegistrationDate()}).
 * The server date is rolled forward over weekends (see {@link BusinessDay}) so it matches the
 * adjusted registration dates the new and existing owners carry. Reads only the existing owners,
 * so it can run before the new owner is built.
 */
public class EnsureDailyOwnerLimit {

    /** The maximum number of owners that may be created on a single business day. */
    static final int DAILY_LIMIT = 100;

    public void service(OwnerRepository ownerRepository) throws DailyOwnerLimitException {
        LocalDate today = BusinessDay.adjust(LocalDate.now());
        int createdToday = 0;
        for (Owner owner : ownerRepository.findAll()) {
            if (today.equals(owner.getRegistrationDate())) {
                createdToday++;
            }
        }
        if (createdToday >= DAILY_LIMIT) {
            throw new DailyOwnerLimitException(DAILY_LIMIT);
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.net.URI;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.http.ResponseEntity;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;

public class RespondWithOwnerCreated {

    public void service(@Val Owner owner, OwnerMapper ownerMapper,
            ObjectResponse<ResponseEntity<OwnerDto>> response) {
        OwnerDto dto = ownerMapper.toOwnerDto(owner);
        response.send(ResponseEntity.created(URI.create("/api/owners/" + owner.getId())).body(dto));
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Step of {@code POST /api/owners}: records the new owner's {@code namesakeCount} — the
 * number of existing owners that already share the same first and last name (compared
 * case-insensitively, see {@link Namesake}). It runs on the built owner before
 * {@link SaveOwner} persists it, so the new owner is not yet counted among its own
 * namesakes. The value is stored with the row and returned unchanged on later reads.
 */
public class CountNamesakes {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (Namesake.matches(existing, owner.getFirstName(), owner.getLastName())) {
                count++;
            }
        }
        owner.setNamesakeCount(count);
    }
}

